import{_ as s,o as t,c as a,a2 as r}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Assessment","description":"The CAF/WAF assessment platform — how scoring works, what it needs, and what it can assess.","frontmatter":{"description":"The CAF/WAF assessment platform — how scoring works, what it needs, and what it can assess."},"headers":[],"relativePath":"assessment/index.md","filePath":"assessment/index.md"}'),n={name:"assessment/index.md"};function o(i,e,d,h,l,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h1><p>Add <code>-Assessment</code> and AzureScout stops being an inventory tool and becomes a scored review: it collects, applies declarative rule files, and produces a <code>findings.json</code> with per-area scores, a prioritised gap list, and evidence for every finding.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it answers</th></tr></thead><tbody><tr><td><a href="./assessment.html">Assessment platform</a></td><td>Architecture, the collect → ingest → assess → report flow, run modes, the registry, and scoring</td></tr><tr><td><a href="./analysis-features.html">Analysis features</a></td><td>Cross-run drift, cost anomaly detection, IaC gap detection, IoT deep coverage</td></tr><tr><td><a href="./configuration.html">Configuration and report tiers</a></td><td>Saving/loading config, the three live outputs, and held legacy renderers</td></tr><tr><td><a href="./assessment-prerequisites.html">Prerequisites</a></td><td>What assessment mode needs beyond a normal inventory run</td></tr><tr><td><a href="./assessment-permissions.html">Auth and permissions per scan type</a></td><td>The minimum RBAC and Graph permissions each assessment needs</td></tr></tbody></table><h2 id="what-can-be-assessed" tabindex="-1">What can be assessed <a class="header-anchor" href="#what-can-be-assessed" aria-label="Permalink to &quot;What can be assessed&quot;">​</a></h2><p>The full list lives on one generated page — <strong><a href="./../reference/assessment-catalogue.html">Assessment Catalogue</a></strong> — covering all 46 assessments grouped into CAF design areas, WAF pillars, per-service slices, and specialised reviews, with the rule files and rule counts behind each.</p><h2 id="read-this-before-quoting-a-score" tabindex="-1">Read this before quoting a score <a class="header-anchor" href="#read-this-before-quoting-a-score" aria-label="Permalink to &quot;Read this before quoting a score&quot;">​</a></h2><p>A rule is either <strong>automated</strong> — decided by collected data — or <strong>manual</strong>, meaning no data Azure exposes can settle it and a human must confirm it. <strong>225 of Scout&#39;s 395 rules (57%) are manual.</strong> They are excluded from every score rather than counted as failures, and reported separately.</p><p>That ratio varies enormously by assessment, and it changes what the output <em>is</em>. Some assessments return a grade; others return a worklist. The catalogue publishes the split per assessment, so check it before assuming a low score means a problem — or that a high one means everything was checked.</p><p>Two related guarantees the reports hold to:</p><ul><li>A control that could not be evaluated reads as <strong>&quot;Not assessed&quot;</strong>, never as a zero and never as a pass. &quot;We did not look&quot; and &quot;we looked and found nothing&quot; are different statements.</li><li>A finding names the resources behind it, so it can be actioned rather than admired.</li></ul>',11)])])}const p=s(n,[["render",o]]);export{u as __pageData,p as default};
